const msg = $json.message || {};
const photos = msg.photo || [];
if (!photos.length) throw new Error('Send one image/photo to the bot.');
const largest = photos[photos.length - 1];
return [{ json: { chat_id: msg.chat && msg.chat.id, file_id: largest.file_id } }];

const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin);
if (!keys.length) throw new Error('Telegram did not return binary image data. Check the Telegram credential/node output.');
const key = keys[0];
return [{ json: { ...item.json, binaryKey: 'image' }, binary: { image: bin[key] } }];

const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || ($json.message && $json.message.content) || $json.response || '';
if (!raw) throw new Error('OmniRoute returned no model content.');
let text = String(raw).trim();
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
let parsed;
try { parsed = JSON.parse(text); } catch (e) { throw new Error('AI did not return valid JSON: ' + e.message + '\nRaw: ' + text.slice(0, 1000)); }
return [{ json: parsed }];
